import{_ as i,a0 as s,w as l,s as m,I as n,x as e,a1 as p,A as r,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse(`{"title":"Linux 的 'sort'命令的七個有趣實例（二） | LCTT x X-CMD","titleTemplate":false,"description":"Linux 的 'sort'命令的七個有趣實例（二） | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 的 'sort'命令的七個有趣實例（二） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 的 'sort'命令的七個有趣實例（二） | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150420 7 Interesting Linux 'sort' Command Examples--Part 2","title":"Linux 的 'sort'命令的七個有趣實例（二）","tag":"201505","desc":""},"relativePath":"201505/20150420 7 Interesting Linux 'sort' Command Examples--Part 2.md","filePath":"[post].md"}`),d={name:"201505/20150420 7 Interesting Linux 'sort' Command Examples--Part 2.md"};function c(u,t,w,x,f,g){const o=s("Link");return l(),m("div",null,[t[17]||(t[17]=n("h1",{id:"linux-的-sort-命令的七個有趣實例-二",tabindex:"-1"},[e("Linux 的 'sort'命令的七個有趣實例（二） "),n("a",{class:"header-anchor",href:"#linux-的-sort-命令的七個有趣實例-二","aria-label":"Permalink to “Linux 的 'sort'命令的七個有趣實例（二）”"},"​")],-1)),n("p",null,[t[1]||(t[1]=e("在",-1)),p(o,{href:"http://www.tecmint.com/sort-command-linux/"},{default:r(()=>[...t[0]||(t[0]=[e("上一篇文章",-1)])]),_:1}),t[2]||(t[2]=e("裏，我們已經探討了關於sort命令的多個例子，如果你錯過了這篇文章，可以點擊下面的鏈接進行閲讀。今天的這篇文章作為上一篇文章的繼續，將討論關於sort命令的剩餘用法，與上一篇一起作為Linux ‘sort’命令的完整指南。",-1))]),n("ul",null,[n("li",null,[p(o,{href:"http://www.tecmint.com/sort-command-linux/"},{default:r(()=>[...t[3]||(t[3]=[e("Linux 的 ‘sort’命令的14個有用的範例（一）",-1)])]),_:1})])]),t[18]||(t[18]=a(`<p>在我們繼續深入之前，先創建一個文本文檔‘month.txt’，並且將上一次給出的數據填進去。</p><pre><code>$ echo -e &quot;mar\\ndec\\noct\\nsep\\nfeb\\naug&quot; &gt; month.txt
$ cat month.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Populate-Content.gif" alt="Populate Content"></p><p>15、 通過使用’M‘選項，對’month.txt‘文件按照月份順序進行排序。</p><pre><code>$ sort -M month.txt
</code></pre><p><strong>注意</strong>:‘sort’命令需要至少3個字符來確認月份名稱。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-by-Month.gif" alt="Sort File Content by Month in Linux"></p><p>16、 把數據整理成方便人們閲讀的形式，比如1K、2M、3G、2T，這裏面的K、G、M、T代表千、兆、吉、梯。 （LCTT 譯註：此處命令有誤，ls 命令應該增加 -h 參數，徑改之）</p><pre><code>$ ls -lh /home/$USER | sort -h -k5
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Content-Human-Readable-Format.gif" alt="Sort Content Human Readable Format"></p><p>17、 在上一篇文章中，我們在例子4中創建了一個名為‘sorted.txt’的文件，在例子6中創建了一個‘lsl.txt’。‘sorted.txt&#39;已經排好序了而’lsl.txt‘還沒有。讓我們使用sort命令來檢查兩個文件是否已經排好序。</p><pre><code>$ sort -c sorted.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Check-File-is-Sorted.gif" alt="Check File is Sorted"></p><p>如果它返回0，則表示文件已經排好序。</p><pre><code>$ sort -c lsl.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Check-File-Sorted-Status.gif" alt="Check File Sorted Status"></p><p>報告無序。存在矛盾……</p><p>18、 如果文字之間的分隔符是空格，sort命令自動地將空格後的東西當做一個新文字單元，如果分隔符不是空格呢？</p><p>考慮這樣一個文本文件，裏面的內容可以由除了空格之外的任何符號分隔，比如‘|’，‘\\’，‘+’，‘.’等……</p><p>創建一個分隔符為+的文本文件。使用‘cat‘命令查看文件內容。</p><pre><code>$ echo -e &quot;21+linux+server+production\\n11+debian+RedHat+CentOS\\n131+Apache+Mysql+PHP\\n7+Shell Scripting+python+perl\\n111+postfix+exim+sendmail&quot; &gt; delimiter.txt
</code></pre><hr><pre><code>$ cat delimiter.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Check-File-Content.gif" alt="Check File Content by Delimiter"></p><p>現在基於由數字組成的第一個域來進行排序。</p><pre><code>$ sort -t &#39;+&#39; -nk1 delimiter.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-File-By-Fields.gif" alt="Sort File By Fields"></p><p>然後再基於非數字的第四個域排序。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Content-By-Non-Numeric.gif" alt="Sort Content By Non Numeric"></p><p>如果分隔符是製表符，你需要在’+‘的位置上用$’\\t’代替，如上例所示。</p><p>19、 對主用户目錄下使用‘ls -l’命令得到的結果基於第五列（‘文件大小’）進行一個亂序排列。</p><pre><code>$ ls -l /home/avi/ | sort -k5 -R 
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Content-by-Column1.gif" alt="Sort Content by Column in Random Order"></p><p>每一次你運行上面的腳本，你得到結果可能都不一樣，因為結果是隨機生成的。</p><p>正如我在上一篇文章中提到的規則2所説——sort命令會將以小寫字母開始的行排在大寫字母開始的行前面。看一下上一篇文章的例3，字符串‘laptop’在‘LAPTOP’前出現。</p><p>20、 如何覆蓋默認的排序優先權？在這之前我們需要先將環境變量LC_ALL的值設置為C。在命令列提示欄中運行下面的代碼。</p><pre><code>$ export LC_ALL=C
</code></pre><p>然後以非默認優先權的方式對‘tecmint.txt’文件重新排序。</p><pre><code>$ sort tecmint.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Override-Sorting-Preferences.gif" alt="Override Sorting Preferences"></p><p><em>覆蓋排序優先權</em></p><p>不要忘記與example 3中得到的輸出結果做比較，並且你可以使用‘-f’，又叫‘-ignore-case’（忽略大小寫）的選項來獲取更有序的輸出。</p><pre><code>$ sort -f tecmint.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Compare-Sorting-Preferences.gif" alt="Compare Sorting Preferences"></p><p>21、 給兩個輸入文件進行‘sort‘，然後把它們連接成一行！</p><p>我們創建兩個文本文檔’file1.txt‘以及’file2.txt‘，並用數據填充，如下所示，並用’cat‘命令查看文件的內容。</p><pre><code>$ echo -e “5 Reliable\\n2 Fast\\n3 Secure\\n1 open-source\\n4 customizable” &gt; file1.txt
$ cat file1.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Populate-Content-with-Number.gif" alt="Populate Content with Numbers"></p><p>用如下數據填充’file2.txt‘。</p><pre><code>$ echo -e “3 RedHat\\n1 Debian\\n5 Ubuntu\\n2 Kali\\n4 Fedora” &gt; file2.txt
$ cat file2.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Populate-File-with-Data.gif" alt="Populate File with Data"></p><p>現在我們對兩個文件進行排序並連接。</p><pre><code>$ join &lt;(sort -n file1.txt) &lt;(sort file2.txt)
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Sort-Join-Two-Files.gif" alt="Sort Join Two Files"></p><p>我所要講的全部內容就在這裏了，希望與各位保持聯繫，也希望各位經常來逛逛。有反饋就在下面評論吧。</p><hr>`,56)),n("p",null,[t[5]||(t[5]=e("via: ",-1)),p(o,{href:"http://www.tecmint.com/linux-sort-command-examples/"},{default:r(()=>[...t[4]||(t[4]=[e("http://www.tecmint.com/linux-sort-command-examples/",-1)])]),_:1})]),n("p",null,[t[9]||(t[9]=e("作者：",-1)),p(o,{href:"http://www.tecmint.com/author/avishek/"},{default:r(()=>[...t[6]||(t[6]=[e("Avishek Kumar",-1)])]),_:1}),t[10]||(t[10]=e(" 譯者：",-1)),p(o,{href:"https://github.com/DongShuaike"},{default:r(()=>[...t[7]||(t[7]=[e("DongShuaike",-1)])]),_:1}),t[11]||(t[11]=e(" 校對：",-1)),p(o,{href:"https://github.com/wxy"},{default:r(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[14]||(t[14]=e("本文由 ",-1)),p(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[12]||(t[12]=[e("LCTT",-1)])]),_:1}),t[15]||(t[15]=e(" 原創翻譯，",-1)),p(o,{href:"http://linux.cn/"},{default:r(()=>[...t[13]||(t[13]=[e("Linux中國",-1)])]),_:1}),t[16]||(t[16]=e(" 榮譽推出",-1))])])}const L=i(d,[["render",c]]);export{S as __pageData,L as default};
